// src/components/layout/Sidebar.js
import React from 'react';
import { NavLink, useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import {
  LayoutDashboard, Users, UserCheck, CreditCard,
  Wallet, BarChart3, LogOut, Building2
} from 'lucide-react';

const navByRole = {
  ADMIN: [
    { to: '/dashboard', icon: LayoutDashboard, label: 'Tableau de bord' },
    { to: '/clients', icon: UserCheck, label: 'Clients' },
    { to: '/loans', icon: CreditCard, label: 'Prêts' },
    { to: '/repayments', icon: Wallet, label: 'Remboursements' },
    { to: '/users', icon: Users, label: 'Utilisateurs' },
  ],
  LOAN_OFFICER: [
    { to: '/dashboard', icon: LayoutDashboard, label: 'Tableau de bord' },
    { to: '/clients', icon: UserCheck, label: 'Clients' },
    { to: '/loans', icon: CreditCard, label: 'Prêts' },
    { to: '/repayments', icon: Wallet, label: 'Remboursements' },
  ],
  CLIENT: [
    { to: '/my-loan', icon: CreditCard, label: 'Mon Prêt' },
    { to: '/my-schedule', icon: BarChart3, label: 'Calendrier' },
  ],
};

export default function Sidebar() {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const links = navByRole[user?.role] || [];

  const handleLogout = async () => {
    await logout();
    navigate('/login');
  };

  const roleLabel = { ADMIN: 'Administrateur', LOAN_OFFICER: 'Agent de crédit', CLIENT: 'Client' };
  const initials = user?.name?.split(' ').map(n => n[0]).join('').toUpperCase().slice(0, 2);

  return (
    <aside style={{
      width: 'var(--sidebar-w)', minHeight: '100vh',
      background: 'var(--primary)', display: 'flex',
      flexDirection: 'column', position: 'fixed', left: 0, top: 0,
      zIndex: 100,
    }}>
      {/* Logo */}
      <div style={{ padding: '24px 20px 20px', borderBottom: '1px solid rgba(255,255,255,0.08)' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
          <div style={{
            width: 32, height: 32, background: 'var(--accent)',
            borderRadius: 8, display: 'flex', alignItems: 'center', justifyContent: 'center'
          }}>
            <Building2 size={16} color="#fff" />
          </div>
          <div>
            <div style={{ fontFamily: 'var(--font-heading)', color: '#fff', fontSize: 15, fontWeight: 700, letterSpacing: 0.5 }}>MLMS</div>
            <div style={{ color: 'rgba(255,255,255,0.45)', fontSize: 10 }}>Microfinance</div>
          </div>
        </div>
      </div>

      {/* Nav */}
      <nav style={{ flex: 1, padding: '16px 12px' }}>
        {links.map(({ to, icon: Icon, label }) => (
          <NavLink key={to} to={to} style={({ isActive }) => ({
            display: 'flex', alignItems: 'center', gap: 10,
            padding: '9px 12px', borderRadius: 8, marginBottom: 2,
            textDecoration: 'none', fontSize: 13, fontWeight: 500,
            transition: 'all 0.15s',
            background: isActive ? 'rgba(255,255,255,0.12)' : 'transparent',
            color: isActive ? '#fff' : 'rgba(255,255,255,0.6)',
          })}>
            <Icon size={16} />
            {label}
          </NavLink>
        ))}
      </nav>

      {/* User */}
      <div style={{ padding: '16px 12px', borderTop: '1px solid rgba(255,255,255,0.08)' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 10 }}>
          <div style={{
            width: 34, height: 34, borderRadius: '50%',
            background: 'var(--accent)', display: 'flex',
            alignItems: 'center', justifyContent: 'center',
            fontSize: 12, fontWeight: 700, color: '#fff', flexShrink: 0
          }}>{initials}</div>
          <div style={{ overflow: 'hidden' }}>
            <div style={{ color: '#fff', fontSize: 12, fontWeight: 600, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{user?.name}</div>
            <div style={{ color: 'rgba(255,255,255,0.45)', fontSize: 11 }}>{roleLabel[user?.role]}</div>
          </div>
        </div>
        <button onClick={handleLogout} style={{
          width: '100%', display: 'flex', alignItems: 'center', gap: 8,
          padding: '8px 12px', borderRadius: 8, border: 'none',
          background: 'rgba(255,255,255,0.06)', color: 'rgba(255,255,255,0.6)',
          fontSize: 12, cursor: 'pointer', transition: 'all 0.15s',
        }}
          onMouseEnter={e => e.currentTarget.style.background = 'rgba(255,255,255,0.12)'}
          onMouseLeave={e => e.currentTarget.style.background = 'rgba(255,255,255,0.06)'}
        >
          <LogOut size={14} /> Déconnexion
        </button>
      </div>
    </aside>
  );
}
